pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0 && _tos.length == v.length);
        // We cannot observe the internal call results directly, so we rely on the invariant that
        // when transfer returns true, it must be because the last internal call succeeded.
        // Since the reference always returns true on success, and the mutant returns false,
        // the rule is: transfer returns true.
        // However, the previous attempts show this fails due to fuzz issues. 
        // We use a different approach: we simulate the last call externally and compare.
        // But this may not match internal state. Instead, we check that
        // the return value of transfer equals the success of calling the last transferFrom externally.
        // This holds for reference (returns true, and last call succeeded) but fails for mutant (returns false).

        // To avoid vm.assume rejection, we limit array length
        vm.assume(_tos.length <= 5);

        bool success = c.transfer(from, caddress, _tos, v);

        // Compute what the last internal call would return
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        uint lastIndex = _tos.length - 1;
        (bool lastCallSuccess,) = caddress.call(abi.encodeWithSelector(id, from, _tos[lastIndex], v[lastIndex]));

        // The rule: transfer returns the same value as the last internal call would return
        assertTrue(success == lastCallSuccess);
    }
}

