// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        // The general rule: if _tos is empty, the call should revert.
        vm.assume(_tos.length == 0);
        // Ensure v length matches _tos length to avoid out-of-bounds access
        vm.assume(v.length == _tos.length);

        // Use try/catch to catch the revert
        try c.transfer(from, caddress, _tos, v) returns (bool) {
            // If it returns without reverting, the assertion fails
            assertTrue(false, "transfer should have reverted with empty array");
        } catch {
            // Revert is the expected behavior
            assertTrue(true);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        // Record the sum of v before the call
        uint sumBefore;
        for (uint i = 0; i < v.length; i++) {
            sumBefore += v[i];
        }

        // Execute transfer
        c.transfer(from, caddress, _tos, v);

        // After the call, the contract should hold no ETH (no payable receive)
        uint sumAfter;
        for (uint i = 0; i < v.length; i++) {
            sumAfter += v[i];
        }

        assertTrue(sumBefore == sumAfter);
    }
}
